  "settings.game.cacheRollingBranches": "Cache development branches (FAF Develop & Beta)",
  "settings.game.cacheRollingBranchesHint": "Keeps each played develop and beta build, so replays from them still play.",
  "settings.game.experimentalBadge": "Experimental",
  "settings.game.cacheRollingBranchesDocTitle": "How development branch caching and replay preservation work",
  "settings.game.cacheRollingBranchesDocOverview": "Rolling branches like FAF Develop and FAF Beta do not have permanent numbered releases on the patch server. When new commits are deployed, older builds are replaced, which normally causes older replays to desync or fail.",
  "settings.game.cacheRollingBranchesDocHowTitle": "Version snapshotting",
  "settings.game.cacheRollingBranchesDocHowDesc": "When enabled, each unique build you play is fingerprinted with its Git commit SHA and composite file hash, then indexed in a local version manifest.",
  "settings.game.cacheRollingBranchesDocReplayTitle": "Replay file changes",
  "settings.game.cacheRollingBranchesDocReplayDesc": "Locally recorded .fafreplay files include git_sha, git_short_sha, and build_signature fields in their JSON header line. This allows the client to restore the exact build during replay playback while remaining completely compatible with other FAF clients.",
  "settings.game.cacheRollingBranchesDocStorageTitle": "Storage efficiency",
  "settings.game.cacheRollingBranchesDocStorageDesc": "Files are hardlinked from the shared cache into version folders without duplicating disk space. You can inspect or prune them in the Cached versions list below.",
