  "settings.discord.richPresence": "Rich Presence",
  "settings.discord.richPresenceHint": "Show the game you host or play on your Discord profile.",
  "settings.discord.disallowJoinsVia": "Disallow joins via Discord",
  "settings.discord.disallowJoinsViaHint": "Keep the status visible, but remove the Join button so nobody can enter your lobby from Discord.",
  "settings.steam.presence": "Steam status",
  "settings.steam.presenceHint": "While you are in a game, Steam shows you playing Forged Alliance and counts the hours; having the client open does not count. Needs Steam running and Forged Alliance in your Steam library. Off unless you turn it on.",
  "settings.steam.confirmButton": "Turn on",
  "settings.steam.confirmTitle": "Turn on the Steam status?",
  "settings.steam.confirmBody": "The client will load Valve's closed-source Steamworks library while you play. It tells Steam when you play Forged Alliance on FAF, and we cannot verify what else the library itself might send to Valve.",
  "settings.steam.trustClosed": "To do that the client has to load Valve's Steamworks library, which is closed source. We choose which of its functions we call, and we call only three (start, keep alive, shut down), but we cannot see or verify what the library itself does or sends to Valve. Turning this on means trusting Valve with that.",
  "settings.steam.trustCalls": "The client itself only tells Steam that you started and stopped playing Forged Alliance. Steam then knows which account played, and from when to when, and shows it to your friends according to your own Steam privacy settings. FAF is a separate client, so without this Steam does not learn when you play on FAF.",
  "settings.steam.trustTitle": "What this sends, and what we cannot check",
