  "tournaments.extras.stageTwo": "Second stage: cut the qualifiers into a playoff bracket",
  "tournaments.extras.stageTwoHint": "One tournament, two stages. The Swiss stage runs first, then the teams that came through are seeded into a bracket on the same page, with no second event and no invites to accept.",
  "tournaments.extras.through": "Teams through",
  "tournaments.extras.bracket": "Bracket",
  "tournaments.extras.playoffMatches": "Playoff matches",
  "tournaments.extras.playoffFinal": "Playoff final",
  "tournaments.extras.finalReplaced": "The single top-2 final above is replaced by the bracket while this is on.",
  "tournaments.extras.tiebreakHint": "Decides the standings between equal records, and with a playoff stage who goes through, the playoff seeds and who picks first.",
  "tournaments.extras.pickOn": "Let the top seeds choose their own opponent",
  "tournaments.extras.pickWhereBracket": "Runs on round one of the bracket.",
  "tournaments.extras.pickWherePlayoffs": "On a Swiss this runs on the playoff bracket, and it can still be changed while the Swiss is played (Manage). Swiss round 1 is drawn by seed, and can be rearranged by hand.",
  "tournaments.extras.pickWhereNothing": "Does nothing on a Swiss with no second stage. Swiss round 1 is drawn by seed, and can be rearranged by hand once the rounds start.",
  "tournaments.extras.whoPicks": "Who picks",
  "tournaments.extras.pickHalf": "The top half of the playoff seeds",
  "tournaments.extras.pickUnbeaten": "Only the unbeaten ({record}); everyone else is drawn",
  "tournaments.extras.pickBottom": "Only the unbeaten ({record}), from the {lowest}s; everyone else is seeded",
  "tournaments.extras.pickWhatHalf": "The top half of the seeds each pick who they play, in seed order, instead of the bracket deciding. Needs a full bracket (4, 8, 16, 32...).",
  "tournaments.extras.pickWhatUnbeaten": "Everyone who went through the Swiss without a loss chooses their playoff opponent, in seed order. The rest are drawn against each other, a different record against each other where possible. Needs a playoff of 4, 8, 16 or 32.",
  "tournaments.extras.pickWhatBottom": "Everyone who went through the Swiss without a loss chooses their playoff opponent from the {lowest}s, in seed order. The rest are paired by seed, the best remaining against the lowest. Seeds follow the standings, then the sum of the scores of the opponents each player beat. Needs a playoff of 4, 8, 16 or 32.",
  "tournaments.extras.minutesHint": "Minutes. 0 means no limit. When a pick runs out of time the standard bracket matchup is used, so one absent player cannot stall the event.",
  "tournaments.extras.stopOn": "End the tournament early, once a set number are left",
  "tournaments.extras.stopHint": "For a qualifier: once the field is down to the number that qualifies, there is nothing left worth playing. The tournament ends by itself at that point and the standings are locked, and nobody is crowned champion.",
